cd /workspace && python3 - <<'PY'
import sys, time
sys.path.insert(0,'/workspace/submission')
from adapter import execute_run
U = 1 << 20

def base(ev, M=2, L=2, R=2, kind=('sff',None), fb=10**9, pb=10**9, batch=8, per=100000):
    if kind[0]=='sff': pol={'kind':'sff'}
    elif kind[0]=='fifo': pol={'kind':'fifo'}
    else: pol={'kind':'wfq','weights':[[0,5]]}
    return {'banks':M,'load_balancers':L,'fifo_bytes':fb,'pifo_bytes':pb,'refill_batch':batch,
            'sample_period':per,'borders':[0,1000,U]+[U+1000*(i+1) for i in range(R-2)] if R>2 else [0,1000,U],
            'policy':pol,'events':ev}

# 1. two-way ping-pong across a big gap
ev=[]; nid=0
for i in range(10000): ev.append(['enqueue',nid,0,7,(i*7919)%U]); nid+=1
ev.append(['save',1])
for i in range(10000): ev.append(['enqueue',nid,0,7,(i*104729)%U]); nid+=1
ev.append(['save',2])
for i in range(20000): ev.append(['restore',1]); ev.append(['restore',2])
t=time.time(); execute_run(base(ev)); print('1 two-way ping-pong 40000 restores: %.2fs' % (time.time()-t))

# 2. six-way round robin across big gaps
ev=[]; nid=0
for k in range(6):
    for i in range(4000): ev.append(['enqueue',nid,0,7,(i*7919+k)%U]); nid+=1
    ev.append(['save',k])
for i in range(4000): ev.append(['restore', i%6])
t=time.time(); execute_run(base(ev)); print('2 six-way round robin 4000 restores: %.2fs' % (time.time()-t))

# 3. save at root, then long branch, then restore-to-root repeatedly with work
ev=[['save',0]]
nid=0
for k in range(200):
    for i in range(50): ev.append(['enqueue',nid,0,9,(i*104729+k)%U]); nid+=1
    for i in range(10): ev.append(['dequeue',2])
    ev.append(['restore',0])
t=time.time(); execute_run(base(ev)); print('3 root-restore branches: %.2fs' % (time.time()-t))

# 4. many saves over a large backlog (K pressure)
ev=[]; nid=0
for i in range(20000): ev.append(['enqueue',nid,0,7,(i*7919)%U]); nid+=1
for k in range(20000): ev.append(['save', k%64])
t=time.time(); execute_run(base(ev)); print('4 20000 saves, 20000 backlog: %.2fs' % (time.time()-t))

# 5. service-heavy with lag accumulation and rank errors
ev=[]; nid=0
for i in range(15000): ev.append(['enqueue',nid,0,7,(i*7919)%U]); nid+=1
for i in range(20000): ev.append(['dequeue',1])
t=time.time(); execute_run(base(ev, M=4,L=2,R=4, batch=32, pb=10**7, fb=10**9)); print('5 15000 enq + 20000 visits: %.2fs' % (time.time()-t))

# 6. fifo rejections + pushout storm
ev=[]; nid=0
for i in range(20000):
    ev.append(['enqueue',nid,0,(i%13)+1,(i*7919)%U]); nid+=1
    if i%2==0: ev.append(['dequeue',1])
    if i%31==0: ev.append(['cancel', (i*3)%nid])
t=time.time(); execute_run(base(ev, M=2,L=1,R=2, batch=32, pb=3000, fb=9000, per=500)); print('6 reject/pushout storm: %.2fs' % (time.time()-t))
